package com.exampro.service;
import com.exampro.dto.ApiDtos.*;import com.exampro.entity.Subject;import com.exampro.exception.*;import com.exampro.repository.SubjectRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional public class SubjectService {private final SubjectRepository repo;public SubjectService(SubjectRepository r){repo=r;}public List<SubjectResponse> all(){return repo.findAll().stream().map(this::dto).toList();}public SubjectResponse get(Long id){return dto(repo.findById(id).orElseThrow(()->new NotFoundException("Subject not found")));}public SubjectResponse create(SubjectRequest r){if(repo.existsByNameIgnoreCase(r.name()))throw new BadRequestException("Subject name already exists");Subject s=new Subject();s.setName(r.name().trim());s.setDescription(r.description());return dto(repo.save(s));}public SubjectResponse update(Long id,SubjectRequest r){Subject s=repo.findById(id).orElseThrow(()->new NotFoundException("Subject not found"));if(repo.findAll().stream().anyMatch(x->!x.getId().equals(id)&&x.getName().equalsIgnoreCase(r.name())))throw new BadRequestException("Subject name already exists");s.setName(r.name().trim());s.setDescription(r.description());return dto(repo.save(s));}public void delete(Long id){if(!repo.existsById(id))throw new NotFoundException("Subject not found");repo.deleteById(id);}private SubjectResponse dto(Subject s){return new SubjectResponse(s.getId(),s.getName(),s.getDescription());}}
